const C=WWContent,K=WWCore,S=WWStore,A=WWArt,$=id=>document.getElementById(id);let profile=K.newProfile('starling'),profiles={},mode='home',subject='math',q=null,hinted=false,resolved=false,round=0,typed='',usedTiles=[],questionRecorded=false,activeSkill=0,misses=0,toastTimer,worldStop=null,activityStop=null,lastFocus=null,loadTicket=0,canSave=true,saveEpoch=0,saveChain=Promise.resolve(),currentJournal='math',learnerChosen=false;
const dirtyProfiles=new Set();let rosterTicket=0;const display=p=>K.displayName(p);
