function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),6000);}
function status(msg,bad=false){$('save-status').textContent=msg;$('save-status').style.color=bad?'#f6ba8a':'#a5c5ca';}
function speak(text,force=false){if(!force&&!profile.voice)return;if(!window.speechSynthesis){toast('Spoken audio is unavailable. A grown-up can read the clue, or use Show me.');return;}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.83;const voices=speechSynthesis.getVoices();const v=voices.find(x=>x.localService&&/^en-US/.test(x.lang))||voices.find(x=>x.localService&&/^en/.test(x.lang));if(v)u.voice=v;u.onerror=()=>toast('The voice could not play. Use the clue or Show me with a grown-up.');speechSynthesis.speak(u);}
function markChange(){profile.revision++;profile.updatedAt=Date.now();save();}
function save(){if(!learnerChosen)return Promise.resolve(false);const snapshot=K.validateProfile(profile),epoch=++saveEpoch;profiles[profile.id]=snapshot;dirtyProfiles.add(snapshot.id);if(!canSave){status('Not saved · export progress before leaving',true);return Promise.resolve(false);}status('Saving this explorer…');const work=S.save(snapshot).then(()=>{if(K.canonical(profiles[snapshot.id])===K.canonical(snapshot))dirtyProfiles.delete(snapshot.id);if(epoch===saveEpoch)status('Saved on this device · readback checked');return true;}).catch(e=>{if(epoch===saveEpoch)status('Not saved · keep a progress copy',true);toast('Your work is in this page, but local saving failed. Use Keep a progress copy.');return false;});saveChain=work;return work;}
async function selectProfile(id){if(!K.validLearnerId(id))return;const ticket=++loadTicket;++saveEpoch;if(worldStop){worldStop();worldStop=null;}stopActivity();$('app').inert=true;$('main').innerHTML='<section class="home"><span class="eyebrow">YOUR OWN EXPLORER</span><h1>Opening your island…</h1><p>Keeping each learner’s progress separate.</p></section>';await saveChain;let p;canSave=true;try{const stored=await S.load(id);p=dirtyProfiles.has(id)&&profiles[id]?K.validateProfile(profiles[id]):stored||profiles[id]||K.newProfile(id);}catch(e){p=profiles[id]||K.newProfile(id);canSave=false;status('Existing progress unreadable · no overwrite',true);toast('Stored progress could not be read. Nothing will be overwritten. Export new work separately.');}if(ticket!==loadTicket)return;learnerChosen=true;profile=p;profiles[id]=p;recentlySeen.math=[];recentlySeen.spelling=[];studioSelected=-1;tracePaths=[];q=null;typed='';$('app').inert=false;applySettings();renderHome();if(canSave)status(dirtyProfiles.has(id)?'Not saved · in-page work kept for this learner':profile.revision?'Loaded saved progress · this device only':'New explorer · saves after the first change',dirtyProfiles.has(id));}
function applySettings(){const back=$('modal').querySelector('[data-action=close]');back.disabled=!learnerChosen;back.hidden=!learnerChosen;back.textContent=learnerChosen?'← Islands':'Choose an explorer';$('voice-toggle').disabled=!learnerChosen;$('voice-toggle').hidden=!learnerChosen;document.querySelector('footer [data-action=export]').disabled=!learnerChosen;document.body.classList.toggle('night',profile.theme==='night');document.body.classList.toggle('motion-off',!profile.motion||reduced.matches);$('profile-pill').textContent='✦ '+display(profile);$('voice-toggle').textContent=profile.voice?'Sound on':'Sound off';}
