function openModal(titleText,eyebrow){$('modal').classList.toggle('arrival-modal',mode==='profiles');stopActivity();if(worldStop){worldStop();worldStop=null;}lastFocus=document.activeElement;$('modal-title').textContent=titleText;$('modal-eyebrow').textContent=eyebrow;let active=$('active-learner');if(!active){active=document.createElement('div');active.id='active-learner';active.className='active-learner';$('modal-title').after(active);}active.textContent='Playing as '+display(profile);$('modal').hidden=false;$('app').inert=true;document.body.style.overflow='hidden';$('voice-toggle').textContent=profile.voice?'Sound on':'Sound off';$('modal-title').tabIndex=-1;$('modal-title').focus();}
function close(){if(!learnerChosen){toast('Choose your explorer to begin.');return;}stopActivity();if(window.speechSynthesis)speechSynthesis.cancel();$('modal').hidden=true;$('modal-body').replaceChildren();$('app').inert=false;document.body.style.overflow='';mode='home';renderHome();if(lastFocus&&lastFocus.isConnected)lastFocus.focus();else $('profile-pill').focus();}
