function finish(heading){stopActivity();$('modal-body').innerHTML=`<canvas id="mission" class="mission-scene"></canvas><div class="end-card"><div class="end-emblem">✦</div><span class="eyebrow">EXPEDITION COMPLETE</span><h3>${heading}</h3><p>You explored, tried ideas, and learned along the way. Pip has a new trail to follow. Make something just for fun—or take a break and come back another day.</p><div class="learn-controls"><button class="primary gold" data-action="studio">Make something →</button><button class="secondary" data-action="close">Back to the islands</button></div><p class="quiet-note">Your world will be here when you return. Keep a progress copy if this device cannot save.</p></div>`;A.mission($('mission'),4,profile.avatar,profile.theme==='night');}
function journal(which='math'){if(!$('modal').hidden)close();mode='journal';currentJournal=which;if(worldStop){worldStop();worldStop=null;}document.querySelectorAll('.navlink').forEach(x=>x.classList.toggle('active',x.dataset.action==='journal'));const bank=C[which];$('main').innerHTML=`<section class="journal"><span class="eyebrow">YOUR LEARNING MAP</span><h1>Small discoveries. Growing possibilities.</h1><p class="quiet-note">This preview has ${C.math.length} math skill seeds and ${C.spelling.length} spelling banks. These are practice activities, not a complete K–12 curriculum or a school placement test.</p><div class="tab-row"><button data-action="journal-math" class="${which==='math'?'selected':''}">Mathematics & geometry</button><button data-action="journal-spelling" class="${which==='spelling'?'selected':''}">Spelling & language</button></div><div class="legend"><span>New = not practiced</span><span>Practicing = evidence growing</span><span>Steady = independent successes on different days</span></div><div class="map-grid">${bank.map((s,i)=>{let st=K.skillStatus(profile.skills[s.id]);return `<button class="skill-card ${st} ${i===profile.levels[which]?'current':''}" data-action="practice-skill" data-subject="${which}" data-index="${i}"><span class="state">${st}</span><small>${escape(s.band)} · ${String(i+1).padStart(2,'0')}</small><strong>${escape(s.title)}</strong><small>${profile.skills[s.id]?profile.skills[s.id].independent+' independent discoveries':'Try a practice mission'}${i===profile.levels[which]?' · Current challenge':''}</small></button>`;}).join('')}</div><div class="source-note" style="margin-top:24px">A higher starting challenge is not mastery of earlier skills. “Steady” is an in-game practice indicator, not a validated academic assessment. Full reasoning tasks, comprehensive grade coverage and educator review are still to come. Science and other subjects are future expansion, not unlocked content in this build.</div></section>`;}
function parent(){mode='parent';openModal('The grown-up corner','PROGRESS, ACCESSIBILITY & HONEST COVERAGE');$('modal-body').innerHTML=`<div class="parent-area"><div class="source-note">Family preview · No child account or real name required. The page is public if you publish it; it has no access-control gate. Progress remains on this device. Profiles are local conveniences, not separate authenticated accounts. These controls are not a security lock. Keep this preview on a family-managed device; do not use it for private school records.</div><div class="parent-grid"><section><h3>Find the right challenge</h3><p>Choose a starting point independently. Three different unaided successes can move that subject forward. Hints and repeated answers do not fast-track progress. Earlier skills return for review. Starting above a skill does not mark it learned.</p><label for="math-start">Math starting challenge</label><select id="math-start">${C.math.map((s,i)=>`<option value="${i}" ${i===profile.levels.math?'selected':''}>${s.band} · ${s.title}</option>`).join('')}</select><label for="spell-start">Spelling starting challenge</label><select id="spell-start">${C.spelling.map((s,i)=>`<option value="${i}" ${i===profile.levels.spelling?'selected':''}>${s.band} · ${s.title}</option>`).join('')}</select><button class="primary" data-action="save-start">Use these starting points</button><p>High-school grades do not form one fixed course order. The bands are approximate content labels, not claims of complete grade coverage.</p></section><section><h3>Make it their world</h3><form id="rename-learner-form"><label for="rename-learner">This learner’s nickname (not a full name)</label><input id="rename-learner" maxlength="24" value="${escape(display(profile))}" autocomplete="off"><button type="submit" class="secondary">Save nickname</button><p id="rename-message" role="status"></p></form><button data-action="profiles" class="secondary">Switch / add learners</button><p>The look and controls are separate from academic level. Older learners can practice early skills without a preschool-only theme.</p><label for="avatar">Explorer</label><select id="avatar"><option value="explorer">The trailblazer</option><option value="princess">The star princess</option><option value="robot">The curious robot</option></select><button class="secondary" data-action="apply-avatar">Choose explorer</button><button class="secondary" data-action="theme">${profile.theme==='day'?'Switch to starlight':'Switch to daybreak'}</button><button class="secondary" data-action="motion">${profile.motion?'Reduce motion':'Enable gentle motion'}</button><button class="secondary" data-action="voice">${profile.voice?'Turn narration off':'Turn narration on'}</button><p>Audio uses your browser’s speech service. Local English voices are preferred; availability and offline behavior depend on the device. No microphone permission is requested. Readable clues and guided practice remain available.</p></section><section><h3>Protect their progress</h3><p>Only Wonderwake’s own IndexedDB database is used. A completed save is read back before success is shown. No fleet orders, permissions or recovery stores are read or changed.</p><button class="primary" data-action="export">Export this explorer</button><button class="secondary" data-action="import">Check / restore a progress file</button><p>Exports are not encrypted. They include this explorer’s practice history and studio creations, not passwords. Checksums detect accidental changes, not who made a file. Save in private Files storage. This is not cloud backup or cross-device sync.</p><p id="export-state" role="status"></p></section><section><h3>Where this voyage leads</h3><p><strong>Playable:</strong> 30 math seed skills, 120 spelling words, 52 letter-tracing guides, three creative studios, and a gentle movement game. K–12 pathways are expandable—not fully taught or certified here.</p><p><strong>Before a public child service:</strong> educator review, broader problem types and assessment validation; accessible testing; parent-managed secure accounts; independent privacy, consent, retention and hosting review. No ads, chat, purchases or automatic analytics are included.</p><p>Content references: Common Core mathematics, Virginia’s 2023 math SOL framework, and IES foundational reading guidance. References inform design; they do not endorse or certify Wonderwake.</p></section></div><section class="fleet-belonging" aria-labelledby="fleet-belonging-title"><span class="eyebrow">BLACK FLAG FLEET · INDEPENDENT LEARNING VESSEL</span><h3 id="fleet-belonging-title">One fleet. Our own adventure.</h3><p>Wonderwake learns from the fleet’s saving, accessibility and testing practices. Its creative interactions can be reviewed for use by other ships. Improvements are adopted deliberately—not pushed automatically.</p><div class="fleet-truth"><strong>Family preview · server commissioning pending</strong><span>24 local learner profiles. No cloud sync or protected child accounts. No learner progress is sent to the fleet.</span></div><p>Different repository paths on the same host share a browser origin. Separate origins and verified server permissions are required before production isolation can be claimed.</p><div class="fleet-actions"><a class="secondary" href="https://jdaniel318-ctrl.github.io/-ikes-wood-signs/" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">Open Black Flag Engine ↗</a><button class="secondary" data-action="fleet-passport">Download public ship passport</button></div><p class="quiet-note">Homeport 0.2.0 · Passport contains release and capability notes only, not live health evidence. Engine authentication remains separate. No automatic registration or fleet changes.</p></section></div>`;$('avatar').value=profile.avatar;$('rename-learner-form').addEventListener('submit',e=>{e.preventDefault();try{const name=K.nickname($('rename-learner').value);if(Object.values(profiles).some(p=>p.id!==profile.id&&display(p).toLowerCase()===name.toLowerCase()))throw Error('That nickname is already in use. Choose another.');profile.nickname=name;markChange();applySettings();$('active-learner').textContent='Playing as '+display(profile);$('rename-message').textContent='Nickname updated for this learner only. Check the save status below.';}catch(err){$('rename-message').textContent=err.message;}});}
async function profilesView(){mode='profiles';const ticket=++rosterTicket;openModal('Choose your explorer','WONDERWAKE · A BLACK FLAG LEARNING SHIP');$('modal-body').innerHTML='<div class="parent-area" role="status">Reading this device’s learners…</div>';let problem='';try{await saveChain;const saved=await S.listProfiles();for(const p of saved)if(!dirtyProfiles.has(p.id))profiles[p.id]=p;}catch(e){problem='Saved learner list could not be read. New learner creation is held; existing records will not be replaced.';}if(mode!=='profiles'||ticket!==rosterTicket)return;const all=[...new Set([...K.ids,...Object.keys(profiles)])].filter(K.validLearnerId);const full=all.length>=K.MAX_LEARNERS;$('active-learner').textContent='Choose a learner before continuing';$('modal-body').innerHTML=`<section class="learner-arrival" aria-label="Welcome to Wonderwake"><div class="arrival-copy"><span class="eyebrow">HOMEPORT · YOUR OWN ADVENTURE</span><h3>A little wonder.<br>A world of possibility.</h3><p>Build a bridge. Discover a word. Make something only you could imagine.</p><span class="arrival-note">Pick your explorer below. Your discoveries stay yours.</span></div><div class="arrival-scene"><canvas id="welcome-world" aria-label="The Wonder Isles, ready to explore"></canvas><span class="arrival-flag">✦ ONE SHIP. MANY ADVENTURES.</span></div></section><div class="roster-intro"><p>Who is setting sail today? Every explorer keeps their own discoveries and creations.</p><div class="roster-tools"><span class="pill">${problem?'Learner list unavailable':all.length+' / '+K.MAX_LEARNERS+' local learners'}</span><button class="primary" data-action="focus-new-learner">+ Add learner</button></div></div>${problem?`<div class="roster-read-error" role="alert"><strong>We could not read the saved learner list.</strong><p>${escape(problem)} The choices below may be incomplete.</p><button class="secondary" data-action="profiles">Try reading learners again</button></div>`:''}<div class="profiles">${all.map(id=>{const p=profiles[id]||K.newProfile(id);return `<button class="profile-card ${learnerChosen&&profile.id===id?'selected':''}" data-action="select-profile" data-id="${id}"><canvas id="avatar-${id}" aria-hidden="true"></canvas><div><h3>${escape(display(p))}</h3><p>Your words. Your discoveries.<br>Your own corner of the islands.</p><small>${learnerChosen&&profile.id===id?'Current explorer':dirtyProfiles.has(id)?'Unsaved work kept in this page':'Let’s explore →'}</small></div></button>`;}).join('')}</div><details id="learner-management" class="parent-area learner-management"><summary>Grown-up tools · add or import learners</summary><div class="learner-management-body"><h3>Add a learner</h3><p>Use a nickname. No real name, date of birth, email or grade is needed. A new learner starts at early math and spelling; a grown-up can set each starting challenge separately.</p><form id="add-learner-form"><label for="learner-nickname">Nickname</label><input id="learner-nickname" maxlength="24" placeholder="For example: Moonbeam" autocomplete="off" required><label for="learner-avatar">Choose an explorer</label><select id="learner-avatar"><option value="princess">The star princess</option><option value="explorer">The trailblazer</option><option value="robot">The curious robot</option></select><button type="submit" class="primary gold" ${problem||full?'disabled':''}>Add learner →</button></form><p id="learner-message" role="status">${escape(problem|| (full?'All 24 local preview slots are in use. Existing progress is unchanged.':'Each learner is saved separately. Adding one does not copy another’s progress.'))}</p><button class="secondary" data-action="import" ${!learnerChosen?'disabled':''}>Check / import a learner’s progress file</button>${!learnerChosen?'<p class="quiet-note">Choose an explorer first to check or import a saved progress file.</p>':''}<p class="quiet-note">This is a family-managed local profile picker, not password-protected child accounts. Someone using this device can open any learner. No cloud sync, classroom records or public leaderboard. Export each learner’s progress privately. Use one active game tab per device.</p></div></details>`;worldStop=A.world($('welcome-world'),()=>({theme:learnerChosen?profile.theme:'day',avatar:learnerChosen?profile.avatar:'explorer',motion:(!learnerChosen||profile.motion)&&!reduced.matches}));applySettings();if(!learnerChosen)$('profile-pill').textContent='Choose explorer';for(const id of all){const p=profiles[id]||K.newProfile(id);const g=A.setup($('avatar-'+id),150,100);A.hero(g,75,84,1.2,p.avatar);}$('add-learner-form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.target.querySelector('button');if(btn.disabled)return;try{const name=K.nickname($('learner-nickname').value);if(all.some(id=>display(profiles[id]||K.newProfile(id)).toLowerCase()===name.toLowerCase()))throw Error('That nickname is already in use. Choose another.');if(!crypto.randomUUID)throw Error('Creating a learner requires a secure HTTPS page.');const p=K.newProfile('learner-'+crypto.randomUUID(),name);p.avatar=$('learner-avatar').value;btn.disabled=true;$('learner-message').textContent='Saving a separate learner record…';const saved=await S.create(p);profiles[p.id]=saved;if(mode!=='profiles'||ticket!==rosterTicket){toast('New learner saved. Open the learner picker to choose them.');return;}$('modal').hidden=true;$('app').inert=false;document.body.style.overflow='';await selectProfile(p.id);status('New learner saved · readback checked');}catch(err){if($('learner-message'))$('learner-message').textContent=err.message;btn.disabled=false;}});}
async function exportProgress(){if(!learnerChosen){toast('Choose the learner whose progress you want to keep.');return;}try{const snapshot=K.validateProfile(profile);const data=await S.pack(snapshot);download(JSON.stringify(data,null,2),`wonderwake-${snapshot.id}-progress.json`,'application/json');toast('Progress download requested. Keep the file privately; reopen it with Check / restore to verify.');if($('export-state'))$('export-state').textContent='Download requested; file saved on your device is not yet verified.';}catch(e){toast(e.message);}}
function download(data,name,type){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('import-file').addEventListener('change',async e=>{const file=e.target.files[0],targetId=profile.id,ticket=loadTicket;e.target.value='';if(!file)return;if(!learnerChosen){toast('Choose a learner before checking a progress file. No records were changed.');return;}try{if(file.size>2000000)throw Error('This file exceeds the 2 MB progress limit.');const incoming=await S.unpack(await file.text());if(ticket!==loadTicket||targetId!==profile.id)throw Error('Learner changed while the file was being checked. Nothing was replaced.');const saved=await S.listProfiles();if(incoming.id!==targetId){const known=K.ids.includes(incoming.id)||saved.some(p=>p.id===incoming.id)||profiles[incoming.id];if(known)throw Error(`File verified for ${display(incoming)}. Switch to that learner before restoring; nothing was replaced.`);if(!confirm(`File verified for ${display(incoming)}. Add this separate learner to this device? Existing learners will not change. Cancel to verify only.`))return;const added=await S.create(incoming);profiles[added.id]=added;if(!$('modal').hidden)close();await selectProfile(added.id);toast('A separate learner was imported. Existing learners were not changed.');return;}if(!confirm(`File verified. Replace ${display(profile)}’s local progress with this saved copy? Other learners will not change. Cancel to verify only.`))return;if(!canSave)throw Error('Existing local progress is unreadable. Restore is held to prevent overwriting it.');await saveChain;await S.save(incoming);if(ticket!==loadTicket)throw Error('File saved to its original learner; active learner has changed.');profile=incoming;profiles[profile.id]=profile;dirtyProfiles.delete(profile.id);applySettings();status('Restored file · local save readback checked');if(!$('modal').hidden)close();renderHome();toast('This learner’s progress was restored. Other learners were not changed.');}catch(err){toast(err.message);}});
